function descargarArchivo(url){oCargando.Mostrar();const link=document.createElement("a");link.href=url;link.style.display="none";document.body.appendChild(link);link.click();document.body.removeChild(link);setTimeout(function(){oCargando.Ocultar()},2e3)}let oCargando=new ModalCargando;document.addEventListener("DOMContentLoaded",function(){const enlacesDescarga=document.querySelectorAll("[data-js-descargar]");enlacesDescarga.forEach(function(enlace){enlace.addEventListener("click",function(e){e.preventDefault();const url=this.getAttribute("href")||this.getAttribute("data-js-descargar");descargarArchivo(url)})})});